(function() {
  var STORAGE_KEY = 'cardspoke_pomodoro_state';
  var CONTAINER_ID = 'cs-pomodoro-container';
  var WORK_DURATION = 25 * 60;
  var SHORT_BREAK = 5 * 60;
  var LONG_BREAK = 15 * 60;
  var SESSIONS_BEFORE_LONG = 4;

  var state = {
    timeRemaining: WORK_DURATION,
    isRunning: false,
    isWorkSession: true,
    completedSessions: 0,
    totalWorkTime: 0,
    intervalId: null,
    isDragging: false,
    dragOffset: { x: 0, y: 0 }
  };

  function loadState() {
    try {
      var saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        var parsed = JSON.parse(saved);
        state.completedSessions = parsed.completedSessions || 0;
        state.totalWorkTime = parsed.totalWorkTime || 0;
        state.isWorkSession = parsed.isWorkSession !== undefined ? parsed.isWorkSession : true;
        state.timeRemaining = parsed.timeRemaining || WORK_DURATION;
      }
    } catch (e) {
      console.warn('[Pomodoro] Failed to load saved state:', e);
    }
  }

  function saveState() {
    try {
      var data = {
        completedSessions: state.completedSessions,
        totalWorkTime: state.totalWorkTime,
        isWorkSession: state.isWorkSession,
        timeRemaining: state.timeRemaining
      };
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    } catch (e) {
      console.warn('[Pomodoro] Failed to save state:', e);
    }
  }

  function clearSavedState() {
    try {
      localStorage.removeItem(STORAGE_KEY);
    } catch (e) {
      console.warn('[Pomodoro] Failed to clear state:', e);
    }
  }

  function formatTime(seconds) {
    var m = Math.floor(seconds / 60);
    var s = seconds % 60;
    return (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
  }

  function requestNotificationPermission() {
    if ('Notification' in window && Notification.permission === 'default') {
      Notification.requestPermission();
    }
  }

  function showNotification(title, body) {
    if ('Notification' in window && Notification.permission === 'granted') {
      try {
        new Notification(title, { body: body, icon: 'data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><text y=".9em" font-size="90">🍅</text></svg>' });
      } catch (e) {
        console.log('[Pomodoro]', title, body);
      }
    }
  }

  function updateDisplay() {
    var timerEl = document.getElementById('cs-pomo-time');
    var statusEl = document.getElementById('cs-pomo-status');
    var sessionsEl = document.getElementById('cs-pomo-sessions');
    var startBtn = document.getElementById('cs-pomo-start');
    if (timerEl) timerEl.textContent = formatTime(state.timeRemaining);
    if (statusEl) statusEl.textContent = state.isWorkSession ? 'Focus Time' : 'Break Time';
    if (sessionsEl) sessionsEl.textContent = 'Sessions: ' + state.completedSessions;
    if (startBtn) startBtn.textContent = state.isRunning ? 'Pause' : 'Start';
    var container = document.getElementById(CONTAINER_ID);
    if (container) {
      container.style.borderColor = state.isWorkSession ? '#e74c3c' : '#27ae60';
    }
  }

  function tick() {
    if (state.timeRemaining <= 0) {
      handleSessionComplete();
      return;
    }
    state.timeRemaining--;
    if (state.isWorkSession) {
      state.totalWorkTime++;
    }
    updateDisplay();
    if (state.timeRemaining % 30 === 0) {
      saveState();
    }
  }

  function handleSessionComplete() {
    stopTimer();
    if (state.isWorkSession) {
      state.completedSessions++;
      var isLongBreak = state.completedSessions % SESSIONS_BEFORE_LONG === 0;
      state.timeRemaining = isLongBreak ? LONG_BREAK : SHORT_BREAK;
      state.isWorkSession = false;
      showNotification('Work session complete!', isLongBreak ? 'Time for a long break (15 min).' : 'Time for a short break (5 min).');
    } else {
      state.timeRemaining = WORK_DURATION;
      state.isWorkSession = true;
      showNotification('Break is over!', 'Time to focus. Session ' + (state.completedSessions + 1) + ' starting.');
    }
    saveState();
    updateDisplay();
  }

  function startTimer() {
    if (state.isRunning) return;
    state.isRunning = true;
    state.intervalId = setInterval(tick, 1000);
    updateDisplay();
  }

  function stopTimer() {
    state.isRunning = false;
    if (state.intervalId) {
      clearInterval(state.intervalId);
      state.intervalId = null;
    }
    updateDisplay();
  }

  function toggleTimer() {
    if (state.isRunning) {
      stopTimer();
    } else {
      startTimer();
    }
    saveState();
  }

  function resetTimer() {
    stopTimer();
    state.timeRemaining = state.isWorkSession ? WORK_DURATION : SHORT_BREAK;
    saveState();
    updateDisplay();
  }

  function resetAllSessions() {
    stopTimer();
    state.completedSessions = 0;
    state.totalWorkTime = 0;
    state.isWorkSession = true;
    state.timeRemaining = WORK_DURATION;
    saveState();
    updateDisplay();
  }

  function initDrag(container) {
    var header = container.querySelector('.cs-pomo-header');
    if (!header) return;
    header.addEventListener('mousedown', function(e) {
      state.isDragging = true;
      var rect = container.getBoundingClientRect();
      state.dragOffset.x = e.clientX - rect.left;
      state.dragOffset.y = e.clientY - rect.top;
      container.style.transition = 'none';
    });
    document.addEventListener('mousemove', function(e) {
      if (!state.isDragging) return;
      var x = e.clientX - state.dragOffset.x;
      var y = e.clientY - state.dragOffset.y;
      x = Math.max(0, Math.min(x, window.innerWidth - 200));
      y = Math.max(0, Math.min(y, window.innerHeight - 100));
      container.style.left = x + 'px';
      container.style.top = y + 'px';
      container.style.right = 'auto';
      container.style.bottom = 'auto';
    });
    document.addEventListener('mouseup', function() {
      if (state.isDragging) {
        state.isDragging = false;
        container.style.transition = '';
      }
    });
  }

  function createUI() {
    if (document.getElementById(CONTAINER_ID)) return;
    var container = document.createElement('div');
    container.id = CONTAINER_ID;
    container.style.cssText = 'position:fixed;bottom:20px;right:20px;width:220px;background:#fff;border:2px solid #e74c3c;border-radius:12px;box-shadow:0 4px 20px rgba(0,0,0,0.15);z-index:10000;font-family:system-ui,-apple-system,sans-serif;overflow:hidden;transition:border-color 0.3s ease;';
    container.innerHTML = '<div class="cs-pomo-header" style="padding:8px 12px;background:#f8f9fa;cursor:move;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #eee;"><span id="cs-pomo-status" style="font-size:12px;font-weight:600;color:#333;">Focus Time</span><span id="cs-pomo-sessions" style="font-size:11px;color:#888;">Sessions: 0</span></div><div style="padding:16px;text-align:center;"><div id="cs-pomo-time" style="font-size:36px;font-weight:700;color:#333;letter-spacing:2px;margin:8px 0;">25:00</div><div style="display:flex;gap:6px;justify-content:center;margin-top:12px;"><button id="cs-pomo-start" style="padding:6px 16px;border:none;background:#e74c3c;color:#fff;border-radius:6px;cursor:pointer;font-size:13px;font-weight:500;">Start</button><button id="cs-pomo-reset" style="padding:6px 12px;border:1px solid #ddd;background:#fff;color:#666;border-radius:6px;cursor:pointer;font-size:13px;">Reset</button><button id="cs-pomo-clear" style="padding:6px 12px;border:1px solid #ddd;background:#fff;color:#999;border-radius:6px;cursor:pointer;font-size:11px;">Clear All</button></div></div>';
    document.body.appendChild(container);
    document.getElementById('cs-pomo-start').addEventListener('click', toggleTimer);
    document.getElementById('cs-pomo-reset').addEventListener('click', resetTimer);
    document.getElementById('cs-pomo-clear').addEventListener('click', resetAllSessions);
    initDrag(container);
  }

  function destroyUI() {
    var container = document.getElementById(CONTAINER_ID);
    if (container) {
      container.parentNode.removeChild(container);
    }
  }

  function cleanup() {
    stopTimer();
    destroyUI();
  }

  CardSpoke_MODS.register({
    name: 'Pomodoro Timer',
    hooks: {
      onAppInit: function() {
        loadState();
        createUI();
        updateDisplay();
        requestNotificationPermission();
        console.log('[Pomodoro] Timer initialized. Completed sessions:', state.completedSessions);
      },
      onEnable: function() {
        loadState();
        createUI();
        updateDisplay();
        console.log('[Pomodoro] Timer enabled');
      },
      onDisable: function() {
        cleanup();
        console.log('[Pomodoro] Timer disabled, UI removed');
      },
      onUninstall: function() {
        cleanup();
        clearSavedState();
        console.log('[Pomodoro] Timer uninstalled, all data cleared');
      }
    }
  });
})()
